var EXTRA=[{dot:"gray",j:"Journal of Robotic Surgery",h:"I guasti dei robot per protesi hanno un'impronta diversa per piattaforma",v:"Analisi delle segnalazioni di sicurezza australiane su cinque sistemi robotici: MAKO soprattutto errori di registrazione, ROSA Recon scostamenti fra piano e resezione ossea, NAVIO/Cori un cluster di guasti software; VELYS presente ma con una sola segnalazione — segnale minimo, non assente.",pmid:'42690546',doi:'10.1007/s11701-026-03890-9',temi:["protesi robotica","dispositivi","sicurezza"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"Nella protesi robotica, un condilo laterale troppo pieno peggiora la rotula",v:"Coorte con sistema MAKO: un femore laterale sovracorretto (nLDFA più valgo, resezione condilare laterale ridotta) si associa a più release del retinacolo e a un tilt rotuleo laterale peggiore dopo l'intervento; direzione dell'effetto chiara nell'abstract, entità non quantificata con un numero unico.",pmid:'42684569',doi:'10.1007/s11701-026-03915-3',temi:["protesi robotica","rotula","tecnica chirurgica"]},{dot:"gray",j:"Journal of Sport and Health Science",h:"Dopo il LCA, l'eccitabilità corticale del quadricipite resta alterata a lungo",v:"Revisione sistematica e meta-analisi di 20 studi: le alterazioni corticospinali e spinali nel quadricipite non si risolvono con la sola riabilitazione precoce e restano misurabili anche al momento del rientro allo sport, associate al deficit di forza residuo.",pmid:'42685978',doi:'10.1016/j.jshs.2026.101171',temi:["lca","riabilitazione","neurofisiologia"]},{dot:"gray",j:"Orthopaedics & Traumatology: Surgery & Research",h:"Più tempo passa dal trauma del LCA, meno vasi nell'osso dell'inserzione femorale",v:"Coorte istologica su prelievi ossei al momento della ricostruzione: oltre i nove mesi dalla lesione la densità dei vasi nel sito femorale di inserzione del LCA scende, e anche il fumo si associa a una vascolarizzazione più povera nello stesso sito.",pmid:'42686093',doi:'10.1016/j.otsr.2026.104869',temi:["lca","biologia","tempistica chirurgica"]},{dot:"gray",j:"JOSPT Open",h:"Dopo LCA su osso-tendine-osso, l'allenamento a bassa intensità con restrizione del flusso tiene testa a quello pesante",v:"RCT piccolo sulla riabilitazione precoce dopo ricostruzione con tendine rotuleo: forza di quadricipite e ischiocrurali, dolore ed effusione articolare sovrapponibili fra i due protocolli; nessuna differenza trovata, ma il campione è ridotto.",pmid:'42686151',doi:'10.2519/josptopen.2026.0185',temi:["lca","riabilitazione","bptb"]},{dot:"gray",j:"The Orthopedic Clinics of North America",h:"Una rassegna in due parti rilegge l'artrosi come malattia dell'intera articolazione",v:"Prima parte di una serie: bersagli terapeutici attuali su cartilagine, sinovia e osso subcondrale nell'artrosi, con il divario ancora aperto fra plausibilità biologica, segnale strutturale e beneficio clinico costante.",pmid:'42692563',doi:'10.1016/j.ocl.2026.05.001',temi:["artrosi","cartilagine","rassegna"]},{dot:"gray",j:"The Orthopedic Clinics of North America",h:"Le società ortopediche restano caute sul PRP nell'artrosi di ginocchio",v:"Rassegna narrativa: effetto biologico plausibile del PRP sull'infiammazione e sulla cartilagine, ma esiti strutturali all'imaging incostanti; le principali società ortopediche non lo raccomandano di routine, solo come opzione per pazienti selezionati che vogliono rinviare la chirurgia.",pmid:'42692565',doi:'10.1016/j.ocl.2026.05.005',temi:["prp","artrosi","orthobiologics"]},{dot:"gray",j:"The Journal of Knee Surgery",h:"Un test col pendolo batte l'occhio del chirurgo nel bilanciare i tessuti molli",v:"Su un simulatore robotico di ginocchio validato, otto chirurghi esperti d'artroplastica indovinano lo spessore corretto del polietilene meno spesso a mano libera che con il test oggettivo del pendolo; risultato di laboratorio, non ancora sul paziente.",pmid:'42685747',doi:'10.1055/a-2939-2643',temi:["protesi totale","tecnica chirurgica","robotica"]},{dot:"gray",j:"Bone & Joint Research",h:"Una scansione laser sostituisce la sonda nel registrare il ginocchio al robot",v:"Su un fantoccio di ginocchio, un sistema di scansione laser (LumaScan) si è dimostrato più accurato e più veloce della registrazione manuale con sonda tracciata; risultato di laboratorio su modello controllato, non ancora testato in sala operatoria.",pmid:'42686203',doi:'10.1302/2046-3758.159.BJR-2025-0617.R2',temi:["protesi robotica","tecnologia","registrazione chirurgica"]},{dot:"gray",j:"Arthroplasty",h:"Una nuova classificazione mette ordine nell'intaglio femorale anteriore in protesi",v:"Proposta di quattro categorie per descrivere quanto la resezione anteriore del femore si avvicina o supera la corticale in protesi totale, con buon accordo fra osservatori diversi; da validare ancora sugli esiti clinici a lungo termine.",pmid:'42687206',doi:'10.1186/s42836-026-00424-4',temi:["protesi totale","classificazione","tecnica chirurgica"]},{dot:"gray",j:"JOSPT Open",h:"Negli adolescenti dopo LCA, il salto simmetrico nasconde ancora asimmetrie di carico",v:"Coorte di ragazzi in tarda riabilitazione dopo ricostruzione del LCA: pur con un'altezza di salto monopodalico quasi simmetrica fra i due arti, angoli e momenti di flessione al ginocchio restano diversi — un segnale di rischio che la sola misura dell'altezza non coglie.",pmid:'42686180',doi:'10.2519/josptopen.2026.0199',temi:["lca adolescente","criterio di rientro","biomeccanica"]},{dot:"gray",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"Un consensus cinese ordina il percorso della protesi ad alta conformità con recupero rapido",v:"Consensus Delphi multidisciplinare cinese: raccomandazioni su selezione del paziente, pianificazione per immagini, gestione perioperatoria e riabilitazione per protesi totale di ginocchio «ad alta conformità» dentro un percorso di recupero rapido (ERAS); contesto sanitario cinese, protesi personalizzata non necessariamente disponibile nel tuo.",pmid:'42642184',doi:'10.7507/1002-1892.202606094',temi:["protesi totale","consensus","recupero rapido"]},{dot:"gray",j:"Archives of Orthopaedic and Trauma Surgery",h:"Un chirurgo esperto impara la monocompartimentale robotica in sei casi",v:"Serie di 30 protesi monocompartimentali mediali con il sistema robotico ROSA (imageless): la curva di apprendimento specifica della piattaforma si stabilizza al sesto caso in un chirurgo già esperto, con scostamenti radiografici piccoli fra piano preoperatorio e risultato.",pmid:'42684455',doi:'10.1007/s00402-026-06497-9',temi:["protesi monocompartimentale","protesi robotica","curva di apprendimento"]}];
var SCOPERTE=[{t:"Un mRNA iniettato nel ginocchio prova a fermare l'artrosi prima che inizi",v:"Nel modello murino, restituire l'organizzazione del collagene di tipo IX con un mRNA veicolato da nanomicelle blocca la progressione verso l'artrosi in una fase pre-clinica identificata con test meccanici sulla cartilagine, prima di qualunque segno visibile al microscopio. Biologia di frontiera nel topo, lontana dall'uomo — ma nella stessa direzione della ricerca rigenerativa sulla cartilagine che segui.",pmid:'42685225',doi:'10.1126/sciadv.aef9739',temi:["artrosi","terapia genica","cartilagine"]},{t:"L'intelligenza artificiale che i robot ortopedici non hanno ancora",v:"Rassegna narrativa sui sei sistemi commerciali oggi in commercio per la chirurgia robotica del ginocchio — VELYS incluso: nessuno è, ad oggi, un sistema davvero autonomo, tutti restano assistenti di precisione guidati dal chirurgo. Il pezzo discute che cosa servirebbe per il passo successivo — percezione continua, apprendimento, digital twin del paziente — più che descrivere una tecnologia già pronta.",pmid:'42678638',doi:'10.1007/s11701-026-03913-5',temi:["intelligenza artificiale","protesi robotica","velys"]},{t:"Una colla bioattiva per riparare il menisco dove il filo di sutura non arriva",v:"Nel modello di coniglio, un adesivo iniettabile di poliuretano che rilascia un fattore di crescita del tessuto connettivo migliora la tenuta meccanica e la guarigione delle lesioni meniscali nella zona avascolare rispetto a sutura, fibrina o adesivo da solo. Il tessuto meniscale nativo non viene pienamente restituito a 12 settimane: biomateriale ancora preclinico, non una tecnica pronta per la sala operatoria.",pmid:'42692232',doi:'10.1016/j.actbio.2026.09.004',temi:["menisco","bioingegneria","biomateriali"]}];
var SOC={"1":{"video":"Un grande studio svedese ha seguito quasi 11 mila calciatori dopo l'intervento di ricostruzione del legamento crociato anteriore, il legamento centrale del ginocchio. La domanda era semplice: il tendine scelto per ricostruirlo cambia il rischio di doverlo rifare? La risposta, in questo studio, è no: che si usi un tendine della coscia posteriore, uno vicino alla rotula, o il tendine del quadricipite, il rischio di reintervento non cambia in modo significativo. Nelle donne però chi riceve il tendine del quadricipite ha una probabilità più alta — quasi doppia — di infortunarsi anche al ginocchio sano nel periodo successivo. È un'osservazione su tanti pazienti reali seguiti nel tempo, non un confronto pianificato in anticipo: non dimostra che sia l'innesto a causare il secondo infortunio. Resta un dato utile per chi segue il percorso di una ricostruzione del crociato con questo tipo di innesto, sempre più diffuso anche fuori dal calcio professionistico."},"2":{"video":"In alcuni pazienti l'artrosi limitata a un solo lato del ginocchio si accompagna a un legamento crociato anteriore che non tiene più. Di solito si tende a preferire la protesi totale in questi casi; uno studio cinese ha provato invece a combinare protesi parziale e ricostruzione del legamento nello stesso intervento. Due tecniche per ricostruire il legamento sono state confrontate: un legamento sintetico e un tendine prelevato dal paziente. Su 60 ginocchia seguite in media cinque anni, i risultati funzionali sono simili nei due gruppi; con il legamento sintetico il recupero nel primo mese è più veloce, con il tendine autologo due pazienti hanno avuto dolore nella zona di prelievo. Sono gruppi piccoli e i pazienti non sono stati assegnati a caso alla tecnica: un risultato interessante, non ancora una conferma solida. Ma apre una possibilità in più quando artrosi parziale e legamento insufficiente convivono nello stesso ginocchio."},"3":{"video":"Lussare completamente il ginocchio, con più legamenti coinvolti insieme, è raro ma può capitare anche negli adolescenti, quando le cartilagini di crescita sono ancora aperte. Un piccolo studio segue quattro ragazzi operati con questa lesione. A distanza di una media di sette anni, nessuno dei quattro ha avuto problemi di crescita, e il recupero funzionale del ginocchio è stato da discreto a ottimo, grazie a un intervento pianificato con attenzione particolare alle cartilagini ancora aperte. Il dato più importante però riguarda la mente, non il ginocchio: tre ragazzi su quattro convivono ancora con un disagio psicologico legato al trauma, anche se il ginocchio funziona bene. Solo quattro casi, ma un segnale da non trascurare nel follow-up di questi pazienti."},"4":{"video":"Quando il legamento crociato posteriore del ginocchio si strappa via da un piccolo frammento osseo, si può riparare senza aprire il ginocchio, solo con l'artroscopio. Una tecnica a tre piccoli tunnel e un ponte di sutura è stata studiata su 22 pazienti. A due anni dall'intervento, i punteggi di funzione e stabilità del ginocchio sono migliorati in modo netto, l'osso è guarito completamente entro tre mesi, e non si sono registrate complicanze. Non c'è un gruppo di confronto con altre tecniche, quindi non si può dire se questa sia la migliore in assoluto. Un commento pubblicato insieme allo studio avverte che è una tecnica impegnativa, da esercitare prima su un cadavere."},"5":{"video":"In Finlandia, un registro nazionale ha confrontato oltre 2.600 protesi totali di ginocchio: metà eseguite con l'aiuto di un braccio robotico, metà con la tecnica tradizionale. La domanda: cambia il rischio di dover ripetere l'intervento entro un anno? Sul rischio complessivo di reintervento, i due gruppi si somigliano molto — la differenza osservata non è abbastanza netta per essere certa. Sul rischio di infezione della protesi nei primi dodici mesi, invece, il gruppo operato col robot ha fatto significativamente meglio. Non è la stessa piattaforma robotica di ogni ospedale, e il confronto sulle revisioni in generale resta ancora incerto. Ma il dato sulle infezioni precoci è un segnale concreto, che vale la pena conoscere quando si valuta la tecnologia robotica in protesi."},"6":{"video":"Per il dolore cronico di ginocchio che non risponde alle cure abituali esiste una procedura non chirurgica, eseguita da un radiologo interventista: l'embolizzazione delle piccole arterie del ginocchio. Un gruppo internazionale di 29 esperti ha ora definito regole condivise su come e quando usarla. Si può considerare dopo almeno tre mesi di terapia conservativa senza risultato, per dolore da artrosi, tendinopatie, chirurgia pregressa o gonfiori ricorrenti del ginocchio. Si esegue con un piccolo accesso in arteria, senza tagli. Non è ancora chiaro quale tipo di sostanza usata per chiudere le arterie sia la migliore. È un'opinione di esperti raggiunta per consenso, non uno studio con pazienti trattati e confrontati fra loro. Non sostituisce la chirurgia quando questa è indicata, ma è un'opzione in più da conoscere, soprattutto per chi non può o non vuole operarsi."}};
var SOCV={"1":{"video":{"chir":["Un registro nazionale svedese, collegato alla federazione calcio, ha seguito 10.693 calciatori dopo ricostruzione primaria del legamento crociato anteriore. La domanda: il tipo di innesto cambia il rischio di doverla rifare?","Risposta: no, non in modo indipendente — né hamstring, né osso-tendine-osso, né tendine quadricipitale predicono da soli la revisione dell'LCA operato, in modelli di Cox aggiustati per età e livello di gioco. Ma nelle giocatrici il quadricipitale si associa a un rischio più alto di lesione del LCA controlaterale: hazard ratio 1,98, intervallo di confidenza 95% da 1,17 a 3,36.","È un registro, non un trial randomizzato: l'associazione nelle donne può riflettere chi riceve quell'innesto, non l'innesto in sé. Per chi usa il tendine quadricipitale come innesto di default, è il primo dato di questa dimensione, su calciatori veri, che tocca direttamente questa scelta — e va nel colloquio pre-operatorio con le pazienti più giovani ed esposte."],"misto":["Un grande studio svedese ha seguito quasi 11 mila calciatori dopo l'intervento di ricostruzione del legamento crociato anteriore, il legamento centrale del ginocchio. La domanda era semplice: il tendine scelto per ricostruirlo cambia il rischio di doverlo rifare?","La risposta, in questo studio, è no: che si usi un tendine della coscia posteriore, uno vicino alla rotula, o il tendine del quadricipite, il rischio di reintervento non cambia in modo significativo. Nelle donne però chi riceve il tendine del quadricipite ha una probabilità più alta — quasi doppia — di infortunarsi anche al ginocchio sano nel periodo successivo.","È un'osservazione su tanti pazienti reali seguiti nel tempo, non un confronto pianificato in anticipo: non dimostra che sia l'innesto a causare il secondo infortunio. Resta un dato utile per chi segue il percorso di una ricostruzione del crociato con questo tipo di innesto, sempre più diffuso anche fuori dal calcio professionistico."],"pazienti":["Un grande studio svedese ha seguito quasi 11 mila calciatori dopo l'intervento per ricostruire il legamento crociato anteriore del ginocchio, quello che si rompe più spesso nello sport.","Buona notizia: il tipo di tendine usato per la ricostruzione non cambia il rischio di dover rifare l'intervento. Nelle donne, però, chi riceve un tendine prelevato dal quadricipite sembra avere più probabilità di infortunarsi anche al ginocchio sano, non a quello operato.","Non è una prova che quel tendine sia sbagliato: è un'osservazione su tantissimi pazienti reali, che aiuta i chirurghi a spiegare meglio i rischi prima dell'intervento, soprattutto alle giovani sportive. La scelta del tendine resta comunque una decisione da discutere con il proprio chirurgo."]},"linkedin":{"chir":["Registro svedese, 10.693 calciatori: il tipo di innesto non predice la revisione del LCA, ma nelle donne il tendine quadricipitale si associa a un rischio più alto di LCA controlaterale (HR 1,98; IC 95% 1,17-3,36).","Coorte nazionale collegata a registro sportivo (Swedish Knee Ligament Registry + Federazione calcistica svedese), 2014-2023, modelli di Cox causa-specifici per sesso, aggiustati per età e livello di gioco preinfortunio. Revisione dell'LCA operato: 10,8% nelle donne, 9,2% negli uomini, senza associazione col tipo di innesto in nessuno dei due sessi. LCA controlaterale: 12,2% nelle donne, 6,9% negli uomini; nelle donne il tendine quadricipitale (vs hamstring, riferimento) è l'unico innesto associato a un rischio più alto, HR 1,98.","Studio osservazionale, non causale: l'associazione può riflettere selezione del paziente. Ma è il primo dato di questa scala specifico sull'innesto quadricipitale e merita di entrare nel colloquio pre-operatorio con le atlete più giovani."],"misto":["Uno studio su quasi 11 mila calciatori svedesi: il tipo di tendine usato per ricostruire il legamento crociato anteriore non cambia il rischio di dover ripetere l'intervento.","Fra chi è tornato in campo, circa 1 giocatore su 10 ha avuto bisogno di una revisione, senza differenze significative fra i vari innesti usati. Nelle giocatrici, chi riceve il tendine del quadricipite risulta avere una probabilità più alta — quasi il doppio — di infortunarsi anche al ginocchio opposto, rispetto a chi riceve un tendine della coscia posteriore.","È un dato di registro, non un confronto sperimentale: non prova un nesso di causa, ma è un'informazione concreta da condividere con le pazienti più giovani e più esposte al gesto sportivo."],"pazienti":["Un ampio studio svedese mostra che il tipo di tendine scelto per ricostruire il legamento crociato anteriore non cambia, da solo, il rischio di dover ripetere l'intervento.","Su quasi 11 mila calciatori seguiti per anni, chi ha ricevuto un tendine dal quadricipite non ha avuto più reinterventi rispetto a chi ha ricevuto altri tipi di innesto. Nelle donne è stata osservata una maggiore frequenza di un nuovo infortunio al ginocchio sano, non a quello operato: un dato da discutere con il proprio chirurgo, non un motivo di allarme.","Nessuna tecnica è priva di rischi, e la scelta dell'innesto resta una decisione personalizzata, presa insieme al chirurgo in base all'età, allo sport praticato e alle caratteristiche del paziente."]},"instagram":{"chir":["🇸🇪 Registro svedese, 10.693 calciatori operati di LCA: il tipo di innesto NON predice la revisione dell'LCA operato.","Ma nelle donne, il tendine quadricipitale si associa a un rischio più alto di LCA controlaterale — HR 1,98 (IC 95% 1,17-3,36) — rispetto all'hamstring. Studio osservazionale, non causale.","[testo a schermo: «Innesto e revisione LCA: nessun legame — controlaterale nelle donne, un segnale da conoscere»] Alimenta la tensione aperta sull'innesto quadricipitale."],"misto":["⚽ Quasi 11 mila calciatori svedesi, un legamento crociato anteriore ricostruito: il tendine scelto non cambia il rischio di doverlo rifare.","Nelle donne, però, chi riceve un tendine dal quadricipite ha una probabilità più alta di infortunarsi anche al ginocchio sano dopo l'intervento — un dato da tenere presente, non un allarme.","[testo a schermo: «L'innesto non cambia il rischio di reintervento — nelle donne, un segnale sul ginocchio sano»] Studio di registro, non un esperimento controllato."],"pazienti":["🦵 Buona notizia da un grande studio svedese sul legamento crociato anteriore: il tipo di tendine usato per ricostruirlo non cambia il rischio di doverlo rifare.","Nelle donne è stata osservata una maggiore frequenza di un nuovo infortunio al ginocchio sano — non a quello operato — con un tipo di tendine in particolare: da parlarne col proprio chirurgo, senza allarmarsi.","[testo a schermo: «Il tendine scelto non aumenta il rischio di rifare l'intervento»] La scelta resta sempre una decisione condivisa col chirurgo."]},"reel":{"chir":["Innesto LCA e revisione: nessuna associazione, in un registro di 10.693 calciatori.","Nelle donne, il quadricipitale porta un HR 1,98 sul LCA controlaterale (IC 95% 1,17-3,36) — non sull'operato.","[testo a schermo: «Quadricipitale · nessun rischio di revisione in più · attenzione al controlaterale nelle donne»] Registro nazionale, non un RCT."],"misto":["Il tendine scelto per ricostruire il crociato anteriore non cambia il rischio di doverlo rifare.","Nelle donne, un tipo di tendine si associa a più infortuni al ginocchio sano — non a quello operato.","[testo a schermo: «11.000 calciatori · stesso rischio di reintervento con ogni innesto»] Un dato di registro, non un esperimento."],"pazienti":["Il tendine usato per ricostruire il legamento del ginocchio non cambia il rischio di rifare l'intervento.","Nelle donne, un tipo in particolare è legato a più infortuni al ginocchio sano dopo l'operazione.","[testo a schermo: «Buona notizia sull'innesto · un dato da chiedere al chirurgo per le pazienti più giovani»]"]}},"2":{"video":{"chir":["Quando l'artrosi di un solo lato del ginocchio si accompagna a un legamento crociato anteriore insufficiente, di solito si evita la protesi parziale. Uno studio cinese su 60 ginocchia prova invece a combinarla con la ricostruzione del LCA nello stesso tempo chirurgico.","Due modi di ricostruire il legamento: un legamento sintetico (LARS) o un tendine autologo, confrontati fra loro e con la protesi parziale isolata su ginocchio con LCA integro. A un follow-up medio di 61 mesi, punteggi funzionali e allineamento sono sovrapponibili nei tre gruppi; il LARS recupera più in fretta nel primo mese, il tendine autologo espone a un piccolo rischio di dolore nel sito di prelievo.","Gruppi piccoli, venti ginocchia ciascuno, abbinati per propensione e non randomizzati: un segnale, non una dimostrazione definitiva. Ma per chi pratica sia la monocompartimentale sia la ricostruzione del LCA, è un dato che allarga le opzioni quando i due problemi coesistono nello stesso ginocchio."],"misto":["In alcuni pazienti l'artrosi limitata a un solo lato del ginocchio si accompagna a un legamento crociato anteriore che non tiene più. Di solito si tende a preferire la protesi totale in questi casi; uno studio cinese ha provato invece a combinare protesi parziale e ricostruzione del legamento nello stesso intervento.","Due tecniche per ricostruire il legamento sono state confrontate: un legamento sintetico e un tendine prelevato dal paziente. Su 60 ginocchia seguite in media cinque anni, i risultati funzionali sono simili nei due gruppi; con il legamento sintetico il recupero nel primo mese è più veloce, con il tendine autologo due pazienti hanno avuto dolore nella zona di prelievo.","Sono gruppi piccoli e i pazienti non sono stati assegnati a caso alla tecnica: un risultato interessante, non ancora una conferma solida. Ma apre una possibilità in più quando artrosi parziale e legamento insufficiente convivono nello stesso ginocchio."],"pazienti":["A volte l'artrosi colpisce solo un lato del ginocchio, ma il legamento crociato anteriore — quello che dà stabilità — non tiene più. Uno studio cinese ha provato a risolvere entrambi i problemi nello stesso intervento, con la protesi parziale.","Su 60 pazienti, il legamento è stato ricostruito in due modi diversi: con un legamento artificiale o con un tendine prelevato dal paziente stesso. A distanza di circa cinque anni, i risultati sono stati simili; con il legamento artificiale il recupero nel primo mese è stato un po' più veloce.","Sono ancora pochi pazienti e la tecnica non è stata scelta a caso: un risultato promettente, non una certezza. È comunque un'opzione in più per chi ha entrambi i problemi insieme."]},"linkedin":{"chir":["Protesi monocompartimentale mediale + ricostruzione LCA nello stesso tempo: LARS o tendine autologo, esiti comparabili a 61 mesi in una coorte cinese di 60 ginocchia (20+20+20, abbinamento per propensione).","ROM, KSS e OKS migliorati in tutti i gruppi vs preoperatorio (p<0,01), nessuna differenza intergruppo al follow-up finale (p>0,05). HKA, slope tibiale e traslazione tibiale anteriore finali comparabili. A 1 mese, ROM e KSS migliori nel gruppo LARS (p<0,05). 2 pazienti nel gruppo tendine autologo hanno riportato dolore al sito di prelievo. Sopravvivenza dell'impianto 100% in tutti i gruppi.","Studio retrospettivo, gruppi piccoli, non randomizzato: un segnale che il LCA insufficiente non deve necessariamente precludere la monocompartimentale, non ancora una raccomandazione consolidata."],"misto":["Quando l'artrosi di un lato del ginocchio si accompagna a un legamento crociato che non tiene più, un intervento combinato — protesi parziale più ricostruzione del legamento — può essere un'opzione.","Uno studio cinese su 60 ginocchia confronta due modi di ricostruire il legamento in questo contesto: un legamento sintetico e un tendine del paziente. A circa cinque anni, i risultati funzionali sono simili; il legamento sintetico dà un recupero più rapido nel primo mese, il tendine autologo un piccolo rischio di dolore nella zona di prelievo.","Gruppi piccoli, non uno studio randomizzato: un'indicazione utile, non ancora una regola consolidata, per una situazione clinica non frequente ma reale."],"pazienti":["Quando l'artrosi limitata colpisce solo un lato del ginocchio ma il legamento centrale non tiene più, un intervento può risolvere entrambi i problemi insieme.","Uno studio su 60 pazienti mostra risultati funzionali simili a distanza di circa cinque anni, sia usando un legamento sintetico sia un tendine del paziente per ricostruire il legamento durante la protesi parziale.","Come sempre, la scelta della tecnica più adatta va discussa con il proprio chirurgo caso per caso."]},"instagram":{"chir":["🦵 Protesi monocompartimentale + LCA nello stesso tempo chirurgico: LARS o tendine autologo, esiti comparabili a 61 mesi (coorte cinese, n=60).","LARS: recupero più rapido a 1 mese. Tendine autologo: 2/20 dolore al sito donatore. Sopravvivenza impianto 100% in tutti i gruppi. Studio retrospettivo, propensity-matched.","[testo a schermo: «Monocompartimentale + LCA insieme · LARS vs tendine, stesso esito a 5 anni»]"],"misto":["🔧 Artrosi di un lato del ginocchio + legamento crociato insufficiente: si possono risolvere insieme, in un solo intervento.","Uno studio cinese su 60 ginocchia: legamento sintetico o tendine del paziente, risultati simili a circa cinque anni; il sintetico recupera più in fretta nel primo mese.","[testo a schermo: «Protesi parziale + LCA nello stesso intervento · due tecniche, stesso risultato a distanza»]"],"pazienti":["🩺 Artrosi solo da un lato del ginocchio e legamento che non tiene più? Un solo intervento può risolvere entrambi i problemi.","Uno studio su 60 pazienti mostra buoni risultati a distanza di circa cinque anni, sia con un legamento artificiale sia con un tendine prelevato dal paziente.","[testo a schermo: «Due problemi, un intervento · risultati simili a 5 anni»]"]},"reel":{"chir":["Monocompartimentale + LCA insieme: LARS o tendine, esiti comparabili a 61 mesi.","n=60, propensity-matched. LARS più veloce a 1 mese; tendine autologo, 2/20 dolore al prelievo.","[testo a schermo: «UKA + ACLR nello stesso tempo · LARS vs autologo, pari a 5 anni»]"],"misto":["Artrosi da un lato + legamento che non tiene: un solo intervento, due tecniche possibili.","Legamento sintetico o tendine del paziente: risultati simili a circa cinque anni.","[testo a schermo: «Protesi parziale + legamento insieme · stesso esito a distanza»]"],"pazienti":["Due problemi al ginocchio, un solo intervento: protesi parziale più ricostruzione del legamento.","Risultati simili a distanza di anni, sia con legamento artificiale sia con tendine del paziente.","[testo a schermo: «Un intervento, due problemi risolti insieme»]"]}},"3":{"video":{"chir":["Le lussazioni tibiofemorali nell'adolescente con cartilagini di crescita ancora aperte sono rare, e le linee guida di trattamento sono quasi tutte pensate per l'adulto. Una serie di quattro casi da un centro di livello 1 prova a colmare il vuoto.","Quattro pazienti, 12-16 anni, tutti con lussazione di tipo Schenck III-L, seguiti in media 7,3 anni dopo un approccio chirurgico differito e calibrato sulla maturità scheletrica: nessun disturbo di crescita, punteggi funzionali da moderati a eccellenti — KOOS 59-92%, IKDC 62-100%.","Il dato che più cambia la pratica non è ortopedico: tre pazienti su quattro riportano disagio psicologico persistente, nonostante il buon recupero fisico. Serie minima, un solo centro — ma un promemoria diretto per chi segue il ginocchio multilegamentoso nell'adolescente, tecnicamente e non solo."],"misto":["Lussare completamente il ginocchio, con più legamenti coinvolti insieme, è raro ma può capitare anche negli adolescenti, quando le cartilagini di crescita sono ancora aperte. Un piccolo studio segue quattro ragazzi operati con questa lesione.","A distanza di una media di sette anni, nessuno dei quattro ha avuto problemi di crescita, e il recupero funzionale del ginocchio è stato da discreto a ottimo, grazie a un intervento pianificato con attenzione particolare alle cartilagini ancora aperte.","Il dato più importante però riguarda la mente, non il ginocchio: tre ragazzi su quattro convivono ancora con un disagio psicologico legato al trauma, anche se il ginocchio funziona bene. Solo quattro casi, ma un segnale da non trascurare nel follow-up di questi pazienti."],"pazienti":["Quando un ginocchio si lussa completamente, con più legamenti coinvolti, è un infortunio grave — raro, ma possibile anche negli adolescenti ancora in crescita.","Uno studio ha seguito per anni quattro ragazzi con questo tipo di infortunio, operati con attenzione a non danneggiare le zone di crescita dell'osso: nessuno ha avuto problemi di crescita, e il ginocchio ha recuperato bene nella maggior parte dei casi.","Ma tre su quattro hanno continuato a convivere con un disagio emotivo legato all'esperienza, anche a ginocchio guarito. È un promemoria importante: dopo un trauma così, il sostegno psicologico conta quanto la riabilitazione fisica."]},"linkedin":{"chir":["Lussazione tibiofemorale in adolescente con fisi aperte: serie di 4 casi, follow-up medio 7,3 anni, nessun disturbo di crescita dopo trattamento differito e calibrato sulla maturità scheletrica.","4 pazienti (2M/2F, 12-16 anni), tutti Schenck III-L, centro traumatologico di livello 1, 2017-2019. Approccio chirurgico in due tempi in 2/4 casi. KOOS 59-92%, IKDC 62-100%, EQ-5D-5L (TTO) 0,36-1,00. 3/4 pazienti riportano disagio psicologico persistente nonostante il recupero funzionale.","Serie minima, un solo centro: non generalizzabile. Ma è uno dei pochi dati diretti sul ginocchio multilegamentoso scheletricamente immaturo, con un messaggio clinico chiaro sullo screening psicosociale."],"misto":["Una grave lussazione del ginocchio, con più legamenti coinvolti, può capitare anche negli adolescenti ancora in crescita. Una piccola serie segue quattro ragazzi operati con questa lesione.","A distanza di una media di sette anni, nessuno ha avuto problemi di crescita ossea, e il recupero funzionale è stato da discreto a ottimo grazie a un intervento pianificato con attenzione alle cartilagini di crescita ancora aperte. Ma tre su quattro riportano ancora disagio psicologico legato al trauma.","Solo quattro casi, un unico centro: un segnale, non una regola. Utile comunque per chi segue adolescenti dopo traumi gravi al ginocchio, anche sul piano del sostegno psicologico."],"pazienti":["Le lussazioni gravi del ginocchio negli adolescenti ancora in crescita sono rare ma possibili. Uno studio segue quattro ragazzi operati con questo tipo di infortunio.","A distanza di anni, il recupero fisico è stato buono nella maggior parte dei casi, senza problemi di crescita ossea. Il dato più importante riguarda però il benessere psicologico: tre ragazzi su quattro convivono ancora con un disagio legato al trauma, pur con un ginocchio ben funzionante.","Un promemoria utile per famiglie e ragazzi: dopo un trauma grave al ginocchio, il recupero psicologico merita la stessa attenzione di quello fisico."]},"instagram":{"chir":["🩻 Lussazione tibiofemorale in adolescente con fisi aperte: 4 casi, follow-up medio 7,3 anni, nessun disturbo di crescita.","KOOS 59-92%, IKDC 62-100% — ma 3/4 pazienti con disagio psicologico persistente nonostante il buon recupero fisico. Serie minima, ma dato diretto sul ginocchio scheletricamente immaturo.","[testo a schermo: «Recupero fisico buono · disagio psicologico in 3 casi su 4»] Screening psicosociale da considerare nel follow-up."],"misto":["🧒 Una grave lussazione del ginocchio, con più legamenti coinvolti, può capitare anche in adolescenza. Quattro casi seguiti per anni.","Nessun problema di crescita ossea, buon recupero funzionale — ma tre ragazzi su quattro convivono ancora con un disagio psicologico legato al trauma.","[testo a schermo: «Il ginocchio guarisce bene · la mente ha bisogno di più tempo»] Solo quattro casi: un segnale, non una regola."],"pazienti":["💙 Dopo una grave lussazione del ginocchio in adolescenza, il corpo spesso guarisce meglio della mente.","In un piccolo gruppo di ragazzi seguiti per anni, il ginocchio ha recuperato bene — ma molti hanno continuato a sentire il peso emotivo dell'esperienza.","[testo a schermo: «Il sostegno psicologico conta quanto la riabilitazione fisica»]"]},"reel":{"chir":["Lussazione tibiofemorale in adolescente: 4 casi, 7,3 anni di follow-up, nessun disturbo di crescita.","Recupero funzionale buono — ma 3/4 con disagio psicologico persistente.","[testo a schermo: «Ginocchio guarito, mente da seguire · 3 casi su 4»]"],"misto":["Grave lussazione del ginocchio in adolescenza: il corpo guarisce, la mente fatica di più.","Quattro ragazzi seguiti per anni: nessun problema di crescita, ma disagio psicologico in tre su quattro.","[testo a schermo: «Recupero fisico sì · sostegno psicologico da non dimenticare»]"],"pazienti":["Dopo un trauma grave al ginocchio in adolescenza, il corpo guarisce spesso prima della mente.","Il ginocchio può tornare a funzionare bene, ma il peso emotivo può restare.","[testo a schermo: «Sostegno psicologico, non solo fisioterapia»]"]}},"4":{"video":{"chir":["La frattura da avulsione tibiale del legamento crociato posteriore si può riparare interamente per via artroscopica, senza aprire il ginocchio. Una serie retrospettiva descrive una tecnica a tre tunnel con ponte di sutura su 22 pazienti.","A 24 mesi minimi, miglioramento netto di range di movimento, IKDC, Lysholm e Tegner (p<0,001 su tutti); la traslazione tibiale posteriore al KT-1000 scende da 8,4 a 2,9 millimetri. Guarigione ossea completa entro tre mesi, nessuna complicanza.","Serie senza gruppo di confronto, livello IV: mostra che la tecnica funziona in questa casistica, non che sia superiore ad altre. L'editoriale che accompagna lo studio è netto: è una tecnica tecnicamente impegnativa, da provare su cadavere prima di portarla in sala."],"misto":["Quando il legamento crociato posteriore del ginocchio si strappa via da un piccolo frammento osseo, si può riparare senza aprire il ginocchio, solo con l'artroscopio. Una tecnica a tre piccoli tunnel e un ponte di sutura è stata studiata su 22 pazienti.","A due anni dall'intervento, i punteggi di funzione e stabilità del ginocchio sono migliorati in modo netto, l'osso è guarito completamente entro tre mesi, e non si sono registrate complicanze.","Non c'è un gruppo di confronto con altre tecniche, quindi non si può dire se questa sia la migliore in assoluto. Un commento pubblicato insieme allo studio avverte che è una tecnica impegnativa, da esercitare prima su un cadavere."],"pazienti":["A volte, in un trauma al ginocchio, il legamento crociato posteriore non si rompe ma strappa via un piccolo pezzo d'osso a cui è attaccato. Si può riparare senza aprire il ginocchio.","In un gruppo di 22 pazienti trattati con questa tecnica meno invasiva, l'osso è guarito bene entro tre mesi e il ginocchio ha recuperato stabilità e movimento in modo netto a due anni, senza complicanze.","È una tecnica che richiede molta esperienza chirurgica. Lo studio non la confronta direttamente con altre tecniche già usate, ma i risultati in questi pazienti sono incoraggianti."]},"linkedin":{"chir":["Frattura da avulsione tibiale del LCP: tecnica artroscopica a 3 tunnel con ponte di sutura, 22 pazienti, risultati clinici e radiologici solidi a 24 mesi minimi.","Serie retrospettiva monocentrica 2020-2023, 33 valutati/22 inclusi (età mediana 27,5, range 15-55). IKDC/Lysholm/Tegner migliorati p<0,001, tutti i pazienti oltre la MCID. KT-1000: 8,4±1,3mm → 2,9±0,7mm (p<0,001). Guarigione ossea completa entro 3 mesi, zero complicanze.","Livello IV, senza gruppo di confronto. L'editoriale di Meyer, Silva-Mendoza e Levy che accompagna lo studio ne segnala la difficoltà tecnica e raccomanda l'allenamento su cadavere prima dell'uso clinico."],"misto":["Una frattura da strappo osseo del legamento crociato posteriore del ginocchio può oggi essere riparata interamente per via artroscopica, senza aprire il ginocchio.","In 22 pazienti trattati con questa tecnica, i punteggi funzionali e la stabilità del ginocchio sono migliorati in modo netto a due anni, con guarigione ossea completa entro tre mesi e nessuna complicanza.","Non è confrontata direttamente con altre tecniche, e un commento pubblicato insieme allo studio sottolinea che richiede una curva di apprendimento importante."],"pazienti":["Una particolare frattura del ginocchio, in cui il legamento crociato posteriore strappa via un frammento osseo, può oggi essere riparata con una tecnica meno invasiva, senza aprire l'articolazione.","In 22 pazienti trattati così, l'osso è guarito bene entro tre mesi e il ginocchio ha recuperato stabilità e movimento, senza complicanze, a due anni dall'intervento.","È una tecnica impegnativa che richiede molta esperienza del chirurgo: i risultati in questi pazienti sono comunque incoraggianti."]},"instagram":{"chir":["🦴 Frattura da avulsione tibiale del LCP: tecnica artroscopica a 3 tunnel, 22 pazienti, IKDC/Lysholm/Tegner tutti p<0,001 a 24 mesi.","KT-1000: da 8,4 a 2,9 mm (p<0,001). Guarigione ossea completa a 3 mesi, zero complicanze. Livello IV, senza confronto.","[testo a schermo: «LCP: riparazione tutta artroscopica · tecnica impegnativa, da provare su cadavere prima»]"],"misto":["🔩 Uno strappo osseo del legamento crociato posteriore del ginocchio si può oggi riparare senza aprire l'articolazione.","In 22 pazienti: netto miglioramento di stabilità e funzione a due anni, guarigione ossea completa entro tre mesi, nessuna complicanza.","[testo a schermo: «Tecnica tutta artroscopica per il crociato posteriore · risultati solidi, ma impegnativa»]"],"pazienti":["🩹 Una particolare frattura del ginocchio può oggi essere riparata senza aprire l'articolazione, solo con piccoli accessi.","In 22 pazienti, l'osso è guarito bene e il ginocchio ha recuperato stabilità e movimento, senza complicanze, a due anni.","[testo a schermo: «Meno invasivo, buoni risultati · una tecnica che richiede grande esperienza»]"]},"reel":{"chir":["LCP: avulsione tibiale riparata tutta in artroscopia, 22 pazienti, KT-1000 da 8,4 a 2,9 mm.","IKDC/Lysholm/Tegner tutti p<0,001 a 24 mesi. Zero complicanze, guarigione ossea a 3 mesi.","[testo a schermo: «3 tunnel, ponte di sutura · risultati solidi, tecnica impegnativa»]"],"misto":["Frattura da strappo del crociato posteriore: oggi si ripara senza aprire il ginocchio.","22 pazienti, netto miglioramento a due anni, guarigione ossea completa a tre mesi.","[testo a schermo: «Tecnica tutta artroscopica · risultati incoraggianti»]"],"pazienti":["Una frattura particolare del ginocchio, riparata senza aprire l'articolazione.","22 pazienti: buon recupero di stabilità e movimento, nessuna complicanza a due anni.","[testo a schermo: «Meno invasivo, stessi buoni risultati»]"]}},"5":{"video":{"chir":["Il Registro Finlandese dell'Artroplastica ha confrontato 1.318 protesi totali di ginocchio robot-assistite, sistema MAKO, con altrettante convenzionali abbinate per propensione. Domanda: la robotica cambia il rischio di dover rioperare entro un anno?","Sulla revisione per qualsiasi causa, no: sopravvivenza 99,1% col robot contro 98,6% con la tecnica convenzionale, hazard ratio 0,61 ma con un intervallo di confidenza che va da 0,28 a 1,34 — troppo ampio per concludere. Sull'infezione periprotesica, invece, il segnale è solido: hazard ratio 0,29, chiaramente a favore del robot.","Piattaforma MAKO, non VELYS — ma lo schema è lo stesso che segui da RACER-Knee in poi: precisione dimostrata, beneficio clinico da dimostrare esito per esito. Qui l'esito che regge è inatteso e specifico: meno infezioni precoci, non meno reinterventi in generale."],"misto":["In Finlandia, un registro nazionale ha confrontato oltre 2.600 protesi totali di ginocchio: metà eseguite con l'aiuto di un braccio robotico, metà con la tecnica tradizionale. La domanda: cambia il rischio di dover ripetere l'intervento entro un anno?","Sul rischio complessivo di reintervento, i due gruppi si somigliano molto — la differenza osservata non è abbastanza netta per essere certa. Sul rischio di infezione della protesi nei primi dodici mesi, invece, il gruppo operato col robot ha fatto significativamente meglio.","Non è la stessa piattaforma robotica di ogni ospedale, e il confronto sulle revisioni in generale resta ancora incerto. Ma il dato sulle infezioni precoci è un segnale concreto, che vale la pena conoscere quando si valuta la tecnologia robotica in protesi."],"pazienti":["Un grande registro finlandese ha confrontato oltre 2.600 protesi totali di ginocchio: alcune eseguite con l'aiuto di un braccio robotico, altre con la tecnica classica.","Sul rischio di dover ripetere l'intervento entro un anno, non è emersa una differenza chiara fra le due tecniche. È risultato invece più basso, con il robot, il rischio di infezione della protesi nei primi mesi dopo l'intervento.","Non significa che il robot sia sempre meglio: lo studio è ancora troppo piccolo per dirlo su tutte le complicanze insieme, ma il dato sulle infezioni è un'informazione utile e solida."]},"linkedin":{"chir":["Registro Finlandese: 1.318 rTKA (MAKO, Triathlon) vs 1.318 cTKA abbinate per propensione. Nessuna differenza sulla revisione complessiva a 12 mesi; sopravvivenza libera da PJI significativamente migliore col robot.","KM 12 mesi: rTKA 99,1% (IC 98,5-99,7) vs cTKA 98,6% (IC 98,0-99,3), HR 0,61 (IC 0,28-1,34), non significativo. PJI-free survival: HR 0,29 (IC 0,10-0,90), significativo. PJI causa più comune di revisione in entrambi i gruppi. Sopravvivenza a fine follow-up: 97,7% vs 97,9%.","Sistema MAKO, non VELYS. Sull'esito primario (revisione complessiva) lo studio è muto — intervallo troppo ampio per concludere. Solo il segnale sull'infezione periprotesica è statisticamente robusto."],"misto":["Un registro nazionale finlandese confronta oltre 2.600 protesi totali di ginocchio: metà eseguite con un sistema robotico, metà con la tecnica convenzionale.","Sul rischio complessivo di dover ripetere l'intervento entro un anno, nessuna differenza chiara è emersa. Sul rischio di infezione precoce della protesi, invece, il gruppo robot-assistito ha fatto significativamente meglio.","Non è ancora un verdetto complessivo sulla tecnologia robotica in protesi, ma un dato specifico e solido sulle infezioni, utile per chi valuta questa tecnologia."],"pazienti":["Un ampio studio di registro in Finlandia confronta protesi totali di ginocchio eseguite con o senza l'aiuto di un braccio robotico.","Il rischio di dover ripetere l'intervento entro un anno è risultato simile nei due gruppi. Il rischio di infezione della protesi nei primi mesi, invece, è risultato più basso con la tecnica robot-assistita.","Un dato utile da conoscere, senza generalizzare: non tutte le tecnologie robotiche sono uguali, e serve tempo per giudicare gli esiti a lungo termine."]},"instagram":{"chir":["🇫🇮 Registro Finlandese: 1.318 rTKA (MAKO) vs 1.318 cTKA. Revisione complessiva a 12 mesi: HR 0,61 (IC 0,28-1,34), non significativo.","Sopravvivenza libera da infezione periprotesica: HR 0,29 (IC 0,10-0,90) — significativa a favore del robot. PJI: causa più comune di revisione in entrambi i gruppi.","[testo a schermo: «Robot vs convenzionale in TKA · stesse revisioni, meno infezioni precoci»] Sistema MAKO, non VELYS."],"misto":["🤖 Oltre 2.600 protesi di ginocchio in Finlandia: metà col robot, metà con tecnica classica.","Nessuna differenza chiara sul rischio complessivo di reintervento a un anno. Le infezioni precoci, però, sono state significativamente meno frequenti col robot.","[testo a schermo: «Protesi robotica: stesse revisioni, meno infezioni nel primo anno»]"],"pazienti":["🦿 Protesi di ginocchio: con o senza robot, il rischio di dover ripetere l'intervento entro un anno è risultato simile.","Il rischio di infezione precoce, invece, è risultato più basso con la tecnica assistita da robot — un dato utile, non ancora un verdetto definitivo su tutta la tecnologia.","[testo a schermo: «Meno infezioni precoci con il robot in un grande registro nazionale»]"]},"reel":{"chir":["rTKA (MAKO) vs cTKA, registro finlandese: revisione complessiva HR 0,61 (0,28-1,34), muta.","PJI-free survival: HR 0,29 (0,10-0,90) — significativa a favore del robot.","[testo a schermo: «Robot in TKA · stesse revisioni, meno infezioni precoci»]"],"misto":["Protesi di ginocchio col robot: stesso rischio di reintervento, meno infezioni precoci.","Registro finlandese, oltre 2.600 protesi confrontate.","[testo a schermo: «Robot in protesi · un vantaggio specifico sulle infezioni»]"],"pazienti":["Protesi di ginocchio: col robot, meno infezioni nei primi mesi.","Il rischio di dover ripetere l'intervento resta invece simile.","[testo a schermo: «Un vantaggio specifico del robot: meno infezioni precoci»]"]}},"6":{"video":{"chir":["L'embolizzazione delle arterie genicolate è una procedura di radiologia interventistica, non chirurgica, per il dolore cronico di ginocchio. Un panel di 29 radiologi interventisti ha raggiunto, in tre turni Delphi, un primo consensus su indicazioni e tecnica.","Indicazione: dolore refrattario alla terapia conservativa da almeno tre mesi, per artrosi, tendinopatie, pregressa chirurgia o emartro ricorrente. Tecnica: accesso transfemorale omolaterale, embolizzazione di tutte le arterie genicolate con blush ipervascolare. Nessuna superiorità dimostrata fra agenti embolizzanti temporanei o permanenti.","Non è una tua tecnica — livello V, opinione di esperti, nessun dato clinico comparativo. Ma è la prima volta che il progetto la incontra in forma di consensus strutturato: un'alternativa percutanea che i pazienti possono portarti in ambulatorio come opzione già discussa altrove."],"misto":["Per il dolore cronico di ginocchio che non risponde alle cure abituali esiste una procedura non chirurgica, eseguita da un radiologo interventista: l'embolizzazione delle piccole arterie del ginocchio. Un gruppo internazionale di 29 esperti ha ora definito regole condivise su come e quando usarla.","Si può considerare dopo almeno tre mesi di terapia conservativa senza risultato, per dolore da artrosi, tendinopatie, chirurgia pregressa o gonfiori ricorrenti del ginocchio. Si esegue con un piccolo accesso in arteria, senza tagli. Non è ancora chiaro quale tipo di sostanza usata per chiudere le arterie sia la migliore.","È un'opinione di esperti raggiunta per consenso, non uno studio con pazienti trattati e confrontati fra loro. Non sostituisce la chirurgia quando questa è indicata, ma è un'opzione in più da conoscere, soprattutto per chi non può o non vuole operarsi."],"pazienti":["Per il dolore cronico di ginocchio che non passa con le cure abituali, esiste anche una procedura non chirurgica: chiudere, con un piccolo accesso in arteria, alcuni vasi sanguigni intorno al ginocchio che si pensa contribuiscano al dolore.","Un gruppo internazionale di 29 medici esperti ha ora messo per iscritto, insieme, chi può beneficiarne: chi ha dolore da almeno tre mesi, non migliorato con le cure abituali, per artrosi o altre cause del ginocchio.","Non è un'alternativa all'intervento chirurgico quando questo serve davvero, ma può essere un'opzione in più per chi non può o non vuole operarsi — sempre da valutare col proprio medico."]},"linkedin":{"chir":["Genicular Artery Embolization (GAE) per il dolore cronico di ginocchio: primo consensus Delphi, 29 radiologi interventisti, 3 turni, 75 affermazioni valutate su scala Likert a 10 punti.","Indicazioni: dolore refrattario ≥3 mesi da artrosi/tendinopatie/pregressa chirurgia/emartro ricorrente (mediana 9, 86%≥7). Tecnica: accesso transfemorale anterogrado omolaterale, embolizzazione di tutte le arterie con blush ipervascolare (mediana 9, 76%≥7). Nessuna superiorità dimostrata fra agenti temporanei e permanenti (mediana 10, 86%≥7). Follow-up strutturato raccomandato, successo = MCID o soddisfazione del paziente.","Livello V, opinione di esperti: nessun dato clinico comparativo. Non è chirurgia, ma è la prima cornice condivisa di indicazioni per una procedura che i pazienti possono già conoscere da altre fonti."],"misto":["Per il dolore cronico di ginocchio refrattario alle cure abituali, esiste una procedura di radiologia interventistica — non chirurgica — che sta guadagnando una cornice di regole condivise a livello internazionale.","Un panel di 29 esperti ha definito, con un metodo Delphi a tre turni, chi può beneficiarne (dolore da almeno 3 mesi, artrosi o altre cause) e come eseguirla (piccolo accesso arterioso, chiusura mirata di alcuni vasi).","È un consenso di esperti, non uno studio clinico comparativo: indica come si dovrebbe fare la procedura, non ancora quanto funzioni rispetto ad altre opzioni disponibili."],"pazienti":["Per il dolore cronico di ginocchio che non risponde alle terapie abituali, esiste anche un'opzione non chirurgica gestita dalla radiologia interventistica.","Un gruppo internazionale di 29 esperti ha definito regole condivise su chi può trarne beneficio: pazienti con dolore da almeno tre mesi, non risolto da altre cure, per artrosi o altre condizioni del ginocchio.","Non sostituisce la chirurgia quando è indicata, ma può essere una possibilità in più da discutere con il proprio medico."]},"instagram":{"chir":["💉 Genicular Artery Embolization per il dolore cronico di ginocchio: primo consensus Delphi, 29 radiologi interventisti.","Indicazione: dolore refrattario ≥3 mesi. Tecnica: accesso transfemorale, embolizzazione delle arterie con blush ipervascolare. Nessun dato clinico comparativo — livello V.","[testo a schermo: «GAE: non è chirurgia · un primo consensus su indicazioni e tecnica»]"],"misto":["🩹 Dolore cronico di ginocchio che non passa? Esiste anche un'opzione non chirurgica: l'embolizzazione delle arterie del ginocchio.","29 esperti internazionali hanno definito insieme chi può beneficiarne e come si esegue questa procedura percutanea.","[testo a schermo: «Un'alternativa non chirurgica per il dolore cronico di ginocchio»]"],"pazienti":["🔬 Per il dolore cronico di ginocchio che non passa, esiste anche una procedura non chirurgica: chiudere alcuni piccoli vasi sanguigni intorno al ginocchio.","29 esperti nel mondo hanno definito insieme le regole per usarla al meglio.","[testo a schermo: «Un'opzione in più, non un sostituto della chirurgia quando serve»]"]},"reel":{"chir":["GAE per dolore cronico di ginocchio: consensus Delphi, 29 radiologi interventisti, 3 turni.","Indicazione: refrattario ≥3 mesi. Nessun dato clinico comparativo — livello V.","[testo a schermo: «Non chirurgia · consensus su indicazioni e tecnica»]"],"misto":["Dolore cronico di ginocchio: anche un'opzione non chirurgica, dalla radiologia interventistica.","29 esperti nel mondo hanno definito insieme come e su chi usarla.","[testo a schermo: «Un'alternativa percutanea, non ancora confrontata con la chirurgia»]"],"pazienti":["Dolore di ginocchio che non passa? Esiste anche un'opzione non chirurgica.","29 esperti hanno definito insieme le regole per usarla al meglio.","[testo a schermo: «Un'opzione in più da discutere col proprio medico»]"]}}};
var TAGS={"1":{"linkedin":"#ACLReconstruction #SportsMedicine #KneeSurgery","instagram":"#LCA #Ginocchio #ChirurgiaOrtopedica #MedicinaSportiva #Ortopedia #Calcio #Legamenti #SaluteArticolare #Ricerca","kw":"innesto LCA revisione, tendine quadricipitale ginocchio"},"2":{"linkedin":"#KneeArthroplasty #ACLReconstruction #Orthopaedics","instagram":"#ProtesiGinocchio #LCA #Ortopedia #ChirurgiaOrtopedica #Ginocchio #Artrosi #Legamenti #Riabilitazione #Medicina","kw":"protesi parziale ginocchio LCA, legamento sintetico"},"3":{"linkedin":"#KneeDislocation #PediatricOrthopaedics #SportsMedicine","instagram":"#Ginocchio #Adolescenti #Traumatologia #Ortopedia #ChirurgiaOrtopedica #Legamenti #SaluteMentale #Recupero #Sport","kw":"lussazione ginocchio adolescente, trauma multilegamentoso"},"4":{"linkedin":"#PCLReconstruction #Arthroscopy #KneeSurgery","instagram":"#LCP #Ginocchio #Artroscopia #ChirurgiaOrtopedica #Ortopedia #Legamenti #Traumatologia #Recupero #Medicina","kw":"frattura crociato posteriore, tecnica artroscopica"},"5":{"linkedin":"#RoboticSurgery #KneeArthroplasty #Orthopaedics","instagram":"#ProtesiGinocchio #ChirurgiaRobotica #Ortopedia #ChirurgiaOrtopedica #Ginocchio #Infezioni #Registro #SaluteArticolare #Medicina","kw":"protesi ginocchio robot, infezione protesica precoce"},"6":{"linkedin":"#GenicularEmbolization #ChronicPain #InterventionalRadiology","instagram":"#Ginocchio #DoloreCronico #RadiologiaInterventistica #Ortopedia #Artrosi #Medicina #Salute #Innovazione #Ricerca","kw":"embolizzazione arterie genicolate, dolore cronico ginocchio"}};
var NLB={"1":{"prof":["LCA: il tipo di innesto non cambia il rischio di reintervento, un registro svedese","Un registro nazionale svedese collegato alla federazione calcio ha seguito 10.693 calciatori dopo ricostruzione primaria del legamento crociato anteriore: nessuna associazione indipendente fra tipo di innesto — hamstring, osso-tendine-osso o tendine quadricipitale — e rischio di revisione dell'LCA operato. Nelle giocatrici, l'innesto di tendine quadricipitale si associa invece a un rischio più alto di lesione del LCA controlaterale (hazard ratio 1,98; IC 95% 1,17-3,36).","Studio osservazionale su registro, non randomizzato: l'associazione nelle donne può riflettere selezione del paziente più che un effetto diretto dell'innesto, e gli autori stessi non la interpretano come causale."],"mix":["Ricostruzione del crociato anteriore: l'innesto non cambia il rischio di doverla rifare","Uno studio su quasi 11 mila calciatori svedesi mostra che il tipo di tendine usato per ricostruire il legamento crociato anteriore non cambia, da solo, il rischio che l'intervento debba essere rifatto. Nelle donne, però, chi riceve un innesto dal tendine del quadricipite ha una probabilità più alta di infortunarsi anche al ginocchio sano nel periodo successivo.","È un'osservazione su dati di registro, non un confronto pianificato in anticipo: non dimostra che sia l'innesto a causare il secondo infortunio, solo che i due fatti compaiono insieme più spesso nelle donne."],"paz":["Dopo l'intervento al legamento del ginocchio, l'innesto scelto non cambia il rischio di doverlo rifare","Un ampio studio svedese su calciatori operati al legamento crociato anteriore del ginocchio mostra che il tipo di tendine usato per la ricostruzione non influisce, da solo, sulla probabilità di dover ripetere l'intervento. Nelle donne è stata osservata una frequenza maggiore di infortunio anche al ginocchio opposto quando si usa il tendine del quadricipite.","Non è una prova che un innesto sia più rischioso di un altro: è un'osservazione su tanti pazienti reali, da discutere sempre con il proprio chirurgo caso per caso."],"kw":"innesto LCA revisione, tendine quadricipitale ginocchio"},"2":{"prof":["Protesi parziale più LCA: legamento sintetico o tendine, esiti sovrapponibili a 5 anni","Coorte cinese di 60 ginocchia abbinate per propensione: protesi monocompartimentale mediale combinata a ricostruzione del LCA con legamento sintetico LARS o tendine autologo mostra punteggi funzionali e allineamento sovrapponibili alla protesi isolata a un follow-up medio di 61 mesi; il gruppo LARS recupera più in fretta nel primo mese, il gruppo con tendine autologo riporta due casi di dolore al sito di prelievo.","Studio retrospettivo con gruppi piccoli (20 per braccio) e abbinamento per propensione, non randomizzazione: la scelta fra le due tecniche non è stata assegnata a caso."],"mix":["Protesi parziale di ginocchio insieme al legamento crociato: due modi di ricostruirlo, stesso risultato a distanza","Quando il legamento crociato anteriore non tiene più insieme a un'artrosi di un solo lato del ginocchio, alcuni chirurghi ricostruiscono il legamento nello stesso intervento della protesi parziale, con un legamento sintetico oppure un tendine del paziente. Uno studio cinese su 60 ginocchia mostra risultati funzionali simili a circa cinque anni nei due gruppi; con il legamento sintetico il recupero nel primo mese è più rapido.","I gruppi sono piccoli e i pazienti non sono stati assegnati a caso alla tecnica: un confronto suggestivo, non definitivo."],"paz":["Quando la protesi parziale di ginocchio va insieme alla ricostruzione del legamento, due tecniche danno risultati simili","In alcuni pazienti la protesi parziale di ginocchio viene eseguita insieme alla ricostruzione del legamento crociato anteriore. Uno studio su 60 pazienti mostra che, a distanza di circa cinque anni, il risultato funzionale è simile sia usando un legamento sintetico sia un tendine prelevato dal paziente stesso; con il legamento sintetico il recupero nel primo mese sembra un po' più rapido.","Nessuna promessa di risultato: la scelta della tecnica resta una decisione da valutare insieme al proprio chirurgo."],"kw":"protesi parziale ginocchio LCA, legamento sintetico LARS"},"3":{"prof":["Lussazione di ginocchio nell'adolescente: recupero fisico buono, disagio psicologico frequente","Serie di 4 pazienti pediatrici e adolescenti (12-16 anni) con lussazione tibiofemorale di tipo Schenck III-L e cartilagini di crescita ancora aperte, seguiti in media 7,3 anni: nessun disturbo di crescita dopo un approccio chirurgico differito calibrato sulla maturità scheletrica; punteggi funzionali da moderati a eccellenti (KOOS 59-92%, IKDC 62-100%), ma 3 pazienti su 4 riportano disagio psicologico persistente nonostante il buon recupero fisico.","Serie di soli quattro casi, un solo centro: non generalizzabile, ma tocca direttamente il ginocchio scheletricamente immaturo, area della tua pratica meno documentata in letteratura."],"mix":["Nell'adolescente, la lussazione del ginocchio guarisce bene nel corpo ma lascia un peso psicologico","Quattro ragazzi fra 12 e 16 anni con una grave lussazione del ginocchio, con più legamenti coinvolti, sono stati seguiti per una media di oltre sette anni dopo un intervento pianificato per rispettare le cartilagini di crescita ancora aperte. Nessuno ha avuto problemi di crescita e il recupero funzionale è stato da discreto a ottimo — ma tre pazienti su quattro convivono ancora con un disagio psicologico legato al trauma, pur stando bene fisicamente.","Sono solo quattro casi di un unico centro: un segnale da tenere presente più che una regola definitiva."],"paz":["Dopo una grave lussazione del ginocchio in adolescenza, il corpo guarisce spesso meglio della mente","In un piccolo gruppo di ragazzi che hanno subito una grave lussazione del ginocchio con più legamenti coinvolti, operati con attenzione a non danneggiare le cartilagini di crescita, il recupero fisico a distanza di anni è stato buono nella maggior parte dei casi. Molti però hanno continuato a convivere con un disagio emotivo legato all'esperienza, anche quando il ginocchio funzionava bene.","Sono pochissimi casi seguiti in un solo ospedale: un segnale, non una regola — ma un promemoria che il recupero psicologico dopo un trauma importante merita la stessa attenzione di quello fisico."],"kw":"lussazione ginocchio adolescente, trauma multilegamentoso"},"4":{"prof":["Frattura da avulsione del crociato posteriore: una tecnica artroscopica a tre tunnel dà buoni risultati a 2 anni","Serie retrospettiva di 22 pazienti (di 33 valutati) con frattura da avulsione tibiale del legamento crociato posteriore, trattati con fissazione artroscopica a tre tunnel e ponte di sutura: miglioramento significativo di range di movimento, IKDC soggettivo, Lysholm e Tegner (p<0,001), traslazione tibiale posteriore ridotta da 8,4±1,3 mm a 2,9±0,7 mm al KT-1000 (p<0,001), consolidamento osseo completo entro 3 mesi, nessuna complicanza.","Livello IV, serie retrospettiva senza gruppo di confronto; l'editoriale che accompagna lo studio segnala la difficoltà tecnica del gesto e raccomanda un allenamento su cadavere prima di eseguirlo dal vivo."],"mix":["Una tecnica tutta artroscopica per la frattura da strappo del legamento crociato posteriore","In 22 pazienti con una frattura da strappo del legamento crociato posteriore, riparata interamente per via artroscopica con un sistema di tre tunnel e ponte di sutura, i punteggi funzionali e la stabilità del ginocchio sono migliorati in modo netto a due anni, con guarigione ossea completa entro tre mesi e nessuna complicanza registrata.","Studio senza gruppo di confronto: mostra che la tecnica funziona in questa casistica, non che sia superiore ad altre. Un commento pubblicato insieme allo studio nota che è tecnicamente impegnativa."],"paz":["Una tecnica meno invasiva per riparare lo strappo osseo del legamento crociato posteriore","In un gruppo di 22 pazienti con una frattura da strappo del legamento crociato posteriore del ginocchio, una tecnica interamente artroscopica — senza aprire il ginocchio — ha permesso una buona guarigione dell'osso e un netto miglioramento della stabilità e della funzione a due anni dall'intervento, senza complicanze.","È una tecnica impegnativa dal punto di vista chirurgico, e lo studio non la confronta direttamente con altre già in uso."],"kw":"frattura crociato posteriore, tecnica artroscopica ginocchio"},"5":{"prof":["Registro finlandese: la protesi robot-assistita non riduce le revisioni, ma taglia le infezioni precoci","1.318 protesi totali di ginocchio robot-assistite (sistema MAKO, impianto Triathlon) confrontate con altrettante convenzionali abbinate per propensione nel Registro Finlandese: sopravvivenza libera da revisione a 12 mesi sovrapponibile (99,1% vs 98,6%; hazard ratio 0,61, IC 95% 0,28-1,34), ma sopravvivenza libera da infezione periprotesica significativamente migliore col robot (hazard ratio 0,29; IC 95% 0,10-0,90).","L'intervallo di confidenza sulla revisione complessiva è ampio: non esclude né un beneficio reale né un peggioramento quasi doppio del rischio. Solo il dato sull'infezione è statisticamente solido."],"mix":["Protesi di ginocchio col robot: nel registro finlandese meno infezioni precoci, non meno reinterventi","Un confronto su oltre 2.600 protesi totali di ginocchio nel registro nazionale finlandese non trova differenze chiare nel rischio complessivo di dover rioperare entro un anno fra tecnica robot-assistita e convenzionale. Il dato più chiaro riguarda le infezioni: sono risultate meno frequenti nel gruppo operato col robot nei primi 12 mesi.","Il confronto sulle revisioni in generale non è abbastanza numeroso per escludere una differenza reale in un senso o nell'altro; solo il dato sulle infezioni è solido."],"paz":["Nel registro finlandese, la protesi di ginocchio col robot riduce le infezioni precoci ma non i reinterventi in generale","Uno studio su oltre 2.600 protesi di ginocchio in Finlandia non trova, al momento, una differenza chiara nel rischio complessivo di dover ripetere l'intervento entro un anno fra la tecnica assistita da robot e quella tradizionale. È risultato invece più basso, con il robot, il rischio di infezione precoce della protesi.","Non è una prova che il robot sia complessivamente meglio o peggio della tecnica tradizionale: lo studio è ancora troppo piccolo per dirlo su tutte le complicanze insieme."],"kw":"protesi ginocchio robot, infezione protesica precoce"},"6":{"prof":["Embolizzazione delle arterie genicolate per il dolore cronico di ginocchio: un primo consensus Delphi","29 radiologi interventisti hanno raggiunto, in tre turni Delphi, un consensus su indicazioni e tecnica dell'embolizzazione delle arterie genicolate per il dolore cronico di ginocchio refrattario alla terapia conservativa da almeno tre mesi (artrosi, tendinopatie, pregressa chirurgia, emartro ricorrente): accesso transfemorale anterogrado omolaterale, embolizzazione di tutte le arterie genicolate con blush ipervascolare, nessuna superiorità dimostrata fra agenti embolizzanti temporanei o permanenti.","Livello V, opinione di esperti tramite metodo Delphi: non è una tua tecnica — è radiologia interventistica, alternativa non chirurgica per pazienti che non vogliono o non possono operarsi."],"mix":["Un gruppo internazionale di radiologi mette ordine sull'embolizzazione delle arterie del ginocchio per il dolore cronico","Ventinove specialisti di radiologia interventistica hanno definito, con un metodo strutturato a più turni, come e su chi si dovrebbe eseguire l'embolizzazione delle piccole arterie del ginocchio per il dolore cronico che non risponde alla terapia conservativa da almeno tre mesi. È una procedura percutanea, non chirurgica, pensata come alternativa per chi non è candidato o non vuole un intervento.","È un'opinione di esperti raggiunta per consenso, non uno studio con pazienti trattati e confrontati: dice come si dovrebbe fare la procedura, non quanto funzioni rispetto ad altre opzioni."],"paz":["Una procedura non chirurgica per il dolore cronico di ginocchio: gli esperti definiscono le regole","Per il dolore cronico di ginocchio che non migliora con le cure abituali esiste una procedura non chirurgica — l'embolizzazione delle piccole arterie del ginocchio, eseguita da un radiologo interventista con un piccolo accesso in arteria — su cui un gruppo internazionale di esperti ha ora definito regole condivise su chi può beneficiarne e come eseguirla.","Non sostituisce la chirurgia quando questa è indicata: è una possibilità in più per chi non può o non vuole operarsi, da valutare con il proprio medico."],"kw":"embolizzazione ginocchio, dolore cronico non chirurgico"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"British Journal of Sports Medicine",h:"Il tipo di innesto non cambia il rischio di reintervento sul LCA",v:"Registro nazionale svedese collegato alla federazione calcio, 10.693 giocatori: nessuna associazione fra tipo di innesto e revisione dell'LCA operato; nelle donne il tendine quadricipitale — il tuo di scelta — si associa invece a un rischio più alto di lesione del LCA controlaterale (HR 1,98).",ax:"Sandon, Forssblad",date:"set 2026",meta:"coorte di registro nazionale collegato, retrospettiva · 10.693 giocatori · [non dichiarato]",pmid:'42692807',doi:'10.1136/bjsports-2026-111547',journal:"British Journal of Sports Medicine",authors:"Sandon A, Forssblad M",design:"Coorte nazionale su registro collegato: tutte le ricostruzioni primarie del LCA in calciatori tesserati in Svezia dal 2014 al 2023, ottenute incrociando il Registro svedese del legamento del ginocchio con la Federazione calcistica svedese. Modelli di Cox causa-specifici, distinti per sesso, aggiustati per età e livello di gioco preinfortunio (Elite/Non-elite/Youth), con l'innesto hamstring come riferimento.",pop:"10.693 giocatori con ricostruzione primaria del LCA; 6.238 (58%) rientrati in almeno una gara ufficiale (RTC). Età media 22±7 anni, follow-up medio 5,2±2,9 anni.",results:"Fra chi è rientrato in campo: revisione dell'LCA nel 10,8% delle donne (232) e nel 9,2% degli uomini (349), senza associazione col tipo di innesto. LCA controlaterale nel 12,2% delle donne (263) e nel 6,9% degli uomini (264). Nelle donne, il tendine quadricipitale si associa a un rischio più alto di LCA controlaterale rispetto all'hamstring (HR 1,98; IC 95% 1,17-3,36). Nessuna differenza per innesto nelle analisi di sensibilità per fascia d'età né nella coorte completa. Età più giovane e livello di gioco preinfortunio più alto restano i correlati più costanti del rischio di un secondo LCA.",concl:"La scelta dell'innesto non è associata in modo indipendente alla revisione dell'LCA, anche fra i giovani calciatori rientrati in campo; nelle donne l'innesto di tendine quadricipitale è risultato associato al rischio di LCA controlaterale. Età e livello di gioco preinfortunio restano i correlati più costanti del rischio di un secondo LCA.",limits:"Studio osservazionale su registro, non randomizzato: l'associazione nelle donne può riflettere selezione del paziente (chi riceve il quadricipitale) più che un effetto diretto dell'innesto · innesto BPTB rappresentato in numero limitato rispetto a hamstring e quadricipitale nel confronto complessivo · nessun dato sul costrutto o sull'eventuale augmentazione laterale associata all'innesto.",perte:"Riguarda esattamente il tuo innesto di default. La buona notizia è che il tendine quadricipitale non risulta svantaggiato sulla revisione dell'LCA operato rispetto agli altri innesti in questa coorte di calciatori. Il segnale sul LCA controlaterale nelle donne merita di entrare nel colloquio pre-operatorio con le pazienti più giovani e più esposte al gesto sportivo, anche se lo studio non stabilisce un nesso causale — alimenta la tensione T1a con il primo dato specifico sul tuo innesto proveniente da un registro nazionale, non da una serie di casi."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Frontiers in Medicine",h:"Protesi parziale più LCA: legamento sintetico o tendine, stessi risultati a 5 anni",v:"Coorte cinese di 60 ginocchia abbinate per propensione: protesi monocompartimentale mediale combinata a ricostruzione del LCA con legamento sintetico LARS o tendine autologo dà punteggi funzionali sovrapponibili alla protesi isolata a 61 mesi; il LARS recupera più in fretta nel primo mese, il tendine autologo espone al dolore del sito di prelievo.",ax:"He … Jiao",date:"ago 2026",meta:"coorte retrospettiva, abbinamento 1:1:1 per propensione · 60 ginocchia (20+20+20) · [non dichiarato]",pmid:'42688006',doi:'10.3389/fmed.2026.1935913',journal:"Frontiers in Medicine",authors:"He, Yuan, Luo, Li, Peng, Sun, Yin, Leng, Jiao",design:"Coorte retrospettiva monocentrica, gennaio 2019-dicembre 2021: protesi monocompartimentale mediale fixed-bearing combinata a ricostruzione del LCA con legamento sintetico LARS (L-UKA, n=20) o tendine autologo (A-UKA, n=20), confrontate con protesi monocompartimentale isolata su ginocchio con LCA integro, abbinata 1:1:1 per propensione (UKA, n=20).",pop:"60 ginocchia in totale (20 per gruppo). Follow-up medio 61,07±3,90 mesi (poco più di 5 anni).",results:"ROM, Knee Society Score (KSS) e Oxford Knee Score (OKS) migliorati in modo significativo in tutti i gruppi rispetto al preoperatorio (p<0,01), senza differenze significative fra gruppi al follow-up finale (p>0,05). HKA, slope tibiale posteriore e traslazione tibiale anteriore finali comparabili fra gruppi. La traslazione tibiale anteriore preoperatoria era maggiore in L-UKA e A-UKA rispetto a UKA isolata (p<0,01), ma si è normalizzata dopo l'intervento. A 1 mese, ROM e KSS migliori nel gruppo L-UKA rispetto ad A-UKA (p<0,05). 2 pazienti del gruppo A-UKA hanno riportato dolore al sito di prelievo del tendine. Nessun allentamento di impianto né progressione dell'artrosi laterale; sopravvivenza dell'impianto 100%.",concl:"La protesi monocompartimentale combinata a ricostruzione del LCA, con legamento LARS o con tendine autologo, corregge efficacemente la traslazione tibiale anteriore patologica e raggiunge esiti a medio termine comparabili alla protesi isolata; il LARS evita la morbidità del sito donatore e offre un recupero funzionale precoce migliore, ma la sua sicurezza a lungo termine richiede ulteriore validazione.",limits:"Studio retrospettivo con gruppi piccoli (20 per braccio) e abbinamento per propensione, non randomizzazione: la scelta fra LARS e tendine autologo non è stata assegnata a caso · monocentrico, popolazione cinese: trasferibilità al tuo contesto da verificare · nessun dato sulla resistenza a lungo termine del legamento sintetico oltre i 5 anni di follow-up medio.",perte:"Tocca due delle tue tecniche insieme — protesi monocompartimentale e ricostruzione del LCA — nello scenario meno comune del ginocchio artrosico con crociato insufficiente, dove oggi la cautela abituale predilige la protesi totale. Il segnale che il LCA insufficiente possa essere corretto nello stesso tempo chirurgico senza compromettere la sopravvivenza a 5 anni della monocompartimentale è di interesse, ma il legamento sintetico LARS non è il tendine autologo che usi tu, e il campione resta piccolo."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"European Journal of Trauma and Emergency Surgery",h:"Lussazione di ginocchio nell'adolescente: recupero fisico buono, disagio psicologico frequente",v:"Serie di 4 pazienti (12-16 anni) con lussazione tibiofemorale di tipo Schenck III-L e cartilagini di crescita ancora aperte, seguiti in media 7,3 anni: nessun disturbo di crescita, punteggi funzionali da moderati a eccellenti, ma 3 pazienti su 4 riportano disagio psicologico persistente nonostante il buon recupero fisico.",ax:"Hepp, Youssef, Henkelmann",date:"set 2026",meta:"serie di casi retrospettiva-prospettica, monocentrica · 4 pazienti · [non applicabile, dichiarato dagli autori]",pmid:'42690414',doi:'10.1007/s00068-026-03309-y',journal:"European Journal of Trauma and Emergency Surgery",authors:"Hepp, Youssef, Henkelmann",design:"Serie di casi retrospettiva-prospettica, monocentrica, centro traumatologico di livello 1, pazienti trattati fra il 2017 e il 2019 per lussazione tibiofemorale del ginocchio con cartilagini di crescita ancora aperte (età <18 anni). Esiti funzionali e qualità di vita valutati con KOOS, IKDC ed EQ-5D-5L al follow-up più recente.",pop:"4 pazienti (2 maschi, 2 femmine), età 12-16 anni, tutti con lussazione Schenck di tipo III-L. Follow-up medio 7,3 anni (range 6-8).",results:"RM precoce e imaging vascolare hanno identificato lesioni meniscali e condrali associate, fratture da avulsione e, in un caso, una lesione del nervo peroneale. Approccio chirurgico differito e in due tempi in 2 pazienti su 4. Nessun disturbo di crescita né deformità rilevati al follow-up disponibile. Esiti funzionali variabili da moderati a eccellenti (KOOS 59-92%, IKDC 62-100%); valori di utilità EQ-5D-5L (TTO) fra 0,36 e 1,00; disagio psicologico persistente riportato da 3 pazienti su 4 nonostante il buon recupero fisico.",concl:"Le lussazioni tibiofemorali pediatriche possono verificarsi dopo traumi ad alta o bassa energia e richiedono una gestione tempestiva e individualizzata; una ricostruzione differita e calibrata sulla maturità scheletrica appare sicura ed efficace, con esiti funzionali favorevoli e senza disturbi di crescita nel follow-up a lungo termine. Punteggi funzionali favorevoli non si sono però tradotti uniformemente in una qualità di vita corrispondente, ed è raccomandato uno screening psicosociale sistematico nel follow-up di questi pazienti.",limits:"Serie di soli 4 casi, un solo centro: non generalizzabile · nessun gruppo di confronto né standard di trattamento validato specificamente per questa fascia d'età, gli autori lo dichiarano esplicitamente · disagio psicologico rilevato senza uno strumento validato dedicato, come osservazione qualitativa nel follow-up.",perte:"Tocca direttamente la parte della tua pratica meno documentata in letteratura: il ginocchio multilegamentoso nell'adolescente scheletricamente immaturo. Il dato che più cambia il modo di seguire questi pazienti non è chirurgico ma clinico: un buon recupero funzionale del ginocchio non garantisce affatto un buon recupero psicologico, e vale la pena chiederlo esplicitamente al controllo, non solo misurare ROM e stabilità."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Una tecnica tutta artroscopica per la frattura da strappo del crociato posteriore",v:"Serie retrospettiva di 22 pazienti (di 33 valutati): fissazione artroscopica a 3 tunnel con ponte di sutura per la frattura da avulsione tibiale del LCP, miglioramento netto di IKDC/Lysholm/Tegner e della traslazione tibiale posteriore a 24 mesi, nessuna complicanza; un editoriale di accompagnamento segnala che la tecnica è tecnicamente impegnativa.",ax:"Ren … Liu",date:"set 2026",meta:"serie retrospettiva senza gruppo di confronto · 22 pz (di 33 valutati) · [IV]",pmid:'42681948',doi:'10.1002/arj.70502',journal:"Arthroscopy",authors:"Ren, Liu, Wu, Zhang, Li, Liu",design:"Serie retrospettiva monocentrica, gennaio 2020-giugno 2023: fissazione artroscopica a 3 tunnel tibiali (anteriore, posteromediale, posterolaterale) con ponte di sutura per fratture da avulsione tibiale del legamento crociato posteriore (LCP), radiologicamente confermate, follow-up minimo 24 mesi.",pop:"33 pazienti valutati, 22 inclusi secondo i criteri predefiniti (13 uomini, 9 donne; età mediana 27,5 anni, range 15-55). Follow-up 24-40 mesi.",results:"Miglioramento significativo di range di movimento, IKDC soggettivo, Lysholm e Tegner rispetto al preoperatorio (tutti p<0,001); tutti i pazienti hanno raggiunto o superato la differenza minima clinicamente importante su questi tre punteggi, sia a 1 anno sia al follow-up finale. Traslazione tibiale posteriore al KT-1000 ridotta da 8,4±1,3 mm preoperatori a 2,9±0,7 mm al follow-up finale (p<0,001). Radiografie e TC hanno confermato riduzione anatomica immediata e guarigione ossea completa entro 3 mesi; nessuna complicanza correlata alla procedura.",concl:"La fissazione artroscopica a 3 tunnel con ponte di sutura per le fratture da avulsione tibiale del LCP produce un miglioramento significativo di funzione e stabilità del ginocchio a un follow-up minimo di 2 anni, con guarigione ossea soddisfacente e nessuna complicanza; tutti i pazienti hanno raggiunto la differenza minima clinicamente importante sui punteggi funzionali principali.",limits:"Livello IV, serie retrospettiva senza gruppo di confronto con altre tecniche (open o artroscopiche diverse) · popolazione eterogenea per età (15-55 anni), sottogruppi non analizzati separatamente · il commento editoriale che accompagna lo studio (Meyer, Silva-Mendoza, Levy) segnala che la tecnica richiede una curva di apprendimento importante e ne raccomanda l'allenamento su cadavere prima dell'uso clinico.",perte:"Il legamento crociato posteriore è fra le tue ricostruzioni legamentose: questa tecnica a 3 tunnel per l'avulsione tibiale è un'alternativa interamente artroscopica alle tecniche a cielo aperto o miste, con risultati clinici solidi in questa casistica ma nessun confronto diretto disponibile. L'avvertenza dell'editoriale — curva di apprendimento ripida, va provata prima su cadavere — è il punto più utile da portare a casa oggi, più del singolo risultato clinico."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Acta Orthopaedica",h:"Registro finlandese: la protesi robotica non riduce le revisioni ma taglia le infezioni precoci",v:"1.318 protesi totali di ginocchio robot-assistite (sistema MAKO) confrontate con altrettante convenzionali nel Registro Finlandese: sopravvivenza libera da revisione a 12 mesi sovrapponibile, ma sopravvivenza libera da infezione periprotesica significativamente migliore col robot (HR 0,29).",ax:"Alakylä … Mäkelä",date:"set 2026",meta:"coorte di registro nazionale, abbinamento per propensione · 1.318+1.318 protesi · [non dichiarato]",pmid:'42690128',doi:'10.2340/17453674.2026.46462',journal:"Acta Orthopaedica",authors:"Alakylä, Sylvestersson, Venäläinen, Eskelinen, Jaroma, Väyrynen, Kukkonen, Mäkelä",design:"Coorte prospettica su Registro Finlandese dell'Artroplastica: tutte le protesi totali di ginocchio robot-assistite (rTKA, sistema MAKO con impianto Triathlon) eseguite in Finlandia da aprile 2021 a maggio 2023, confrontate con un gruppo di controllo di protesi convenzionali (cTKA) abbinato per propensione nello stesso periodo. Endpoint primario: prima revisione per qualsiasi causa entro 12 mesi. Analisi Kaplan-Meier e regressione di Cox.",pop:"1.318 rTKA fixed-bearing confrontate con 1.318 cTKA abbinate per propensione.",results:"Sopravvivenza libera da revisione a 12 mesi: 99,1% (IC 95% 98,5-99,7) per rTKA vs 98,6% (IC 95% 98,0-99,3) per cTKA; hazard ratio 0,61 (IC 95% 0,28-1,34), non significativo. Sopravvivenza libera da infezione periprotesica a 12 mesi significativamente migliore con rTKA (hazard ratio 0,29; IC 95% 0,10-0,90). L'infezione periprotesica è risultata la causa più comune di revisione in entrambi i gruppi. A fine follow-up disponibile, sopravvivenza complessiva stimata 97,7% (IC 95% 94,9-100,0) per rTKA e 97,9% (IC 95% 96,6-99,2) per cTKA.",concl:"Non è stata osservata alcuna differenza nel rischio di revisione per qualsiasi causa fra protesi robot-assistita e convenzionale; tuttavia, nei primi 12 mesi si sono verificate meno revisioni per infezione periprotesica nel gruppo robot-assistito.",limits:"L'intervallo di confidenza sulla revisione complessiva è ampio (0,28-1,34): non esclude né un beneficio reale né un peggioramento quasi doppio del rischio — vedi MUTE · sistema MAKO, non VELYS: la piattaforma robotica non è la stessa che usi tu · follow-up disponibile ancora breve per un esito come la sopravvivenza protesica, che si giudica di solito a 5-10 anni.",perte:"Piattaforma MAKO, non VELYS — ma il tema è lo stesso che segui da RACER-Knee (21 agosto) in poi: la protesi robotica promette precisione, il beneficio clinico va dimostrato esito per esito. Qui il segnale utile è specifico e diverso dal solito: non riguarda dolore o funzione, ma il rischio di infezione periprotesica precoce, ridotto in modo statisticamente solido — un endpoint che a un chirurgo interessa quanto la revisione stessa."},{n:6,mono:"m-gray",dot:"white",sec:"res",j:"Cardiovascular and Interventional Radiology",h:"Un consensus Delphi definisce l'embolizzazione delle arterie genicolate per il dolore cronico",v:"29 radiologi interventisti, in tre turni Delphi: consensus sulle indicazioni (dolore refrattario da almeno 3 mesi, artrosi/tendinopatie/pregressa chirurgia/emartro ricorrente) e sulla tecnica dell'embolizzazione delle arterie genicolate — non è chirurgia, è una procedura percutanea alternativa, riportata qui perché entra nel discorso che i pazienti ti portano in ambulatorio.",ax:"Taheri Amin … Minko",date:"lug 2026",meta:"consensus Delphi, 3 turni · 29 esperti · [V, opinione di esperti]",pmid:'42487072',doi:'10.1007/s00270-026-04547-8',journal:"Cardiovascular and Interventional Radiology",authors:"Taheri Amin, Golzarian … Minko",design:"Consensus Delphi: un gruppo di lavoro ha sviluppato un questionario di 75 affermazioni; un panel di radiologi muscoloscheletrici e interventisti, selezionato per esperienza clinica, competenza scientifica e diversità geografica, ha valutato ogni affermazione su una scala Likert a 10 punti in tre turni. Consenso predefinito come ≥75% delle valutazioni ≥7/10.",pop:"29 radiologi interventisti hanno completato tutti e tre i turni.",results:"Criteri di inclusione per l'embolizzazione delle arterie genicolate (GAE): dolore di ginocchio refrattario alla terapia conservativa da almeno 3 mesi, per artrosi, tendinopatie o pregressa chirurgia del ginocchio, ed emartro ricorrente (mediana 9, IQR 7-10; 86% ≥7). Valutazione preprocedurale: misure di esito standardizzate, esame clinico e radiografie del ginocchio; la RM con mezzo di contrasto è opzionale (mediana 8, 7-10; 79% ≥7). Tecnica: accesso transfemorale anterogrado omolaterale, cateterizzazione ed embolizzazione di tutte le arterie genicolate visibili con blush ipervascolare (mediana 9, 7-10; 76% ≥7). Nessuna evidenza di superiorità, in sicurezza o efficacia, fra agenti embolizzanti temporanei o permanenti (mediana 10, 8-10; 86% ≥7). Follow-up strutturato a lungo termine raccomandato, con successo clinico definito come raggiungimento della differenza minima clinicamente importante o soddisfazione del paziente (mediana 9, 7-10; 83% ≥7). GAE controlaterale o ripetuta può essere considerata per dolore bilaterale, risposta insufficiente o recidiva del dolore (mediana 8, 7-10; 76% ≥7).",concl:"Questo studio Delphi stabilisce raccomandazioni di consenso per la GAE, basate su indicazioni ampie, tecnica personalizzata sul paziente e un ruolo attivo del radiologo interventista nella cura longitudinale multidisciplinare.",limits:"Livello V, opinione di esperti raggiunta per consenso: nessun dato clinico comparativo su pazienti trattati · procedura di radiologia interventistica, non chirurgica: non fa parte del tuo armamentario né è stata confrontata direttamente con la chirurgia · nessuna informazione sulla durata dell'effetto oltre il follow-up strutturato raccomandato, i cui intervalli non sono specificati nell'abstract.",perte:"Non è una tua tecnica — è radiologia interventistica, non chirurgia — ma è la prima volta che il progetto la incontra in forma di consensus strutturato, non di singolo studio isolato. Vale la pena saperlo esiste perché è il tipo di procedura che un paziente anziano o non operabile può portarti come alternativa già discussa altrove, e ora ha una cornice di indicazioni e tecnica condivisa da un panel internazionale, non solo pratica aneddotica."}];
var SUGGQ=[{"k":"kol","n":"Anna Sandon","w":"Sahlgrenska Sports Medicine Center, Università di Göteborg (Svezia)","r":"Prima autrice dello studio di oggi sul registro svedese collegato alla federazione calcio, che lega tipo di innesto e rischio di revisione/LCA controlaterale nel LCA — corrispondenza tecnica diretta con la tua scelta di innesto quadricipitale e con la tensione T1a; sostituisce la proposta invariata di Brian N. Victoroff (3 settembre)."}];
var BRIEF_TEXT="Oggi sei lavori, uno arancione e nessuno rosso. Il PICK: un registro nazionale svedese collegato alla federazione calcio, 10.693 giocatori, mostra che il tipo di innesto — hamstring, osso-tendine-osso o tendine quadricipitale — non cambia il rischio di revisione del LCA operato; nelle donne, però, il tendine quadricipitale, il tuo di scelta, si associa a un rischio più alto di lesione del LCA controlaterale (hazard ratio 1,98). È il primo dato di questa scala specifico sul tuo innesto, e alimenta la tensione T1a. Fra le altre schede: una coorte cinese combina protesi monocompartimentale e ricostruzione del LCA nello stesso tempo chirurgico, con esiti sovrapponibili a cinque anni fra legamento sintetico LARS e tendine autologo. Una serie di quattro adolescenti con lussazione grave del ginocchio mostra un buon recupero fisico ma un disagio psicologico persistente in tre casi su quattro — un promemoria per lo screening psicosociale, non solo per il controllo del ginocchio. Una tecnica interamente artroscopica ripara la frattura da avulsione del legamento crociato posteriore con buoni risultati a due anni, anche se un editoriale di accompagnamento ne segnala la difficoltà tecnica. Il Registro Finlandese dell'Artroplastica non trova differenze nel rischio di revisione fra protesi robotica e convenzionale, ma osserva meno infezioni periprotesiche precoci col robot — piattaforma MAKO, non VELYS. Chiude la giornata un consensus Delphi sull'embolizzazione delle arterie genicolate per il dolore cronico di ginocchio: non è una tua tecnica, ma un'alternativa non chirurgica che i pazienti possono già conoscere. Il raccoglitore notturno non è passato questa notte: richiami, congressi, società e destino dei verdetti restano non verificati oggi; le ritrattazioni sono state comunque ricontrollate su PubMed per l'intero storico, nessun nuovo esito.";
var BRIEF_DIALOGO=[{"chi":"A","t":"Buongiorno. Sei lavori oggi, uno arancione, nessuno rosso."},{"chi":"B","t":"Partiamo dall'arancione."},{"chi":"A","t":"Un registro svedese su quasi 11 mila calciatori: il tipo di innesto non cambia il rischio di dover rifare l'intervento al crociato anteriore."},{"chi":"B","t":"E per chi usa il tendine quadricipitale, come me, buone notizie?"},{"chi":"A","t":"In parte. Non sei svantaggiato sulla revisione. Ma nelle donne il quadricipitale si associa a un rischio più alto di infortunio al ginocchio sano, non a quello operato — hazard ratio 1,98."},{"chi":"B","t":"Da dire alle pazienti più giovani, allora, nel colloquio prima dell'intervento."},{"chi":"A","t":"Esatto. È il primo dato di un registro di questa scala specifico sul tuo innesto. Cos'altro c'è oggi?"},{"chi":"B","t":"Dimmi."},{"chi":"A","t":"Una coorte cinese combina protesi parziale di ginocchio e ricostruzione del crociato nello stesso intervento — stessi risultati a cinque anni sia con un legamento sintetico sia con un tendine del paziente."},{"chi":"B","t":"E sul fronte adolescenti?"},{"chi":"A","t":"Una serie piccola, solo quattro casi, di lussazioni gravi del ginocchio: il ginocchio recupera bene, ma tre pazienti su quattro convivono ancora con un disagio psicologico."},{"chi":"B","t":"Vale la pena chiederlo al controllo, non solo misurare il ginocchio."},{"chi":"A","t":"Esatto. Poi una tecnica tutta artroscopica per una frattura del legamento crociato posteriore, e un registro finlandese: la protesi robotica non riduce le revisioni ma sembra ridurre le infezioni precoci."},{"chi":"B","t":"E l'ultima scheda?"},{"chi":"A","t":"Non è chirurgia: un consensus di radiologi interventisti sull'embolizzazione delle arterie del ginocchio per il dolore cronico. Utile sapere che esiste, se un paziente te la chiede."},{"chi":"B","t":"Il raccoglitore notturno?"},{"chi":"A","t":"Fermo anche stanotte: richiami e congressi restano non verificati. Le ritrattazioni le abbiamo comunque controllate a mano, nessuna novità."}];
